def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    """
    Calculate delivery fees for each area based on distance in kilometers.
    Fee structure:
    - 0-5 km: KES 200
    - 5-10 km: KES 300
    - 10-15 km: KES 400
    - 15-20 km: KES 500
    - 20+ km: KES 600
    Areas beyond 20 km are not delivered to.
    """
    fees = {}
    for area, km in areas_km.items():
        if km < 0:
            fees[area] = -1
            continue
        if km <= 5:
            fees[area] = 200
        elif km <= 10:
            fees[area] = 300
        elif km <= 15:
            fees[area] = 400
        elif km <= 20:
            fees[area] = 500
        else:
            fees[area] = -1
    return fees
```

