def split_labels(total_cents: int, people: int) -> list[str]:
    if people <= 0:
        raise ValueError("Number of people must be positive")
    if total_cents <= 0:
        raise ValueError("Total cents must be positive")

    per_person_cents = total_cents // people
    remainder = total_cents % people

    labels = []
    for i in range(people):
        if i < remainder:
            labels.append(f"{per_person_cents + 1} cents")
        else:
            labels.append(f"{per_person_cents} cents")

    return labels
```

