from collections import defaultdict

def week_counts(days: list[int]) -> dict[int, int]:
    week_map = defaultdict(int)
    for day in days:
        if 1 <= day <= 7:
            week_map[1] += 1
        elif 8 <= day <= 14:
            week_map[2] += 1
        elif 15 <= day <= 21:
            week_map[3] += 1
        elif 22 <= day <= 28:
            week_map[4] += 1
        elif 29 <= day <= 31:
            week_map[5] += 1
    return dict(week_map)
