def cheapest_dish(codes):
    menu = {
        'A1': 1200,
        'B2': 1500,
        'C3': 1000,
        'D4': 1300,
        'E5': 1100,
    }
    valid_codes = [code for code in codes if code in menu]
    if not valid_codes:
        return ""
    min_price = min(menu[code] for code in valid_codes)
    candidates = [code for code in valid_codes if menu[code] == min_price]
    return min(candidates)
